# Let's try to solve the Social Golfers problem using z3
# 27 golfers, 9 groups of 3, 7 weeks
# No pair of golfers in same group more than once

from z3 import *

# Parameters
N_GOLFERS = 27
N_GROUPS = 9
GROUP_SIZE = 3
N_WEEKS = 7

# Variables: x[w][g][p] = 1 if golfer p is in group g in week w
x = [[[Bool(f'x_{w}_{g}_{p}') for p in range(N_GOLFERS)] for g in range(N_GROUPS)] for w in range(N_WEEKS)]

solver = Solver()

# Each golfer in exactly one group per week
for w in range(N_WEEKS):
    for p in range(N_GOLFERS):
        solver.add(Sum([x[w][g][p] for g in range(N_GROUPS)]) == 1)

# Each group has exactly 3 golfers per week
for w in range(N_WEEKS):
    for g in range(N_GROUPS):
        solver.add(Sum([x[w][g][p] for p in range(N_GOLFERS)]) == 3)

# No pair of golfers in same group more than once
# For each pair (p1, p2), for each week w, for each group g: not (x[w][g][p1] and x[w][g][p2])
# Sum over weeks of (x[w][g][p1] and x[w][g][p2]) <= 1
for p1 in range(N_GOLFERS):
    for p2 in range(p1+1, N_GOLFERS):
        pair_weeks = []
        for w in range(N_WEEKS):
            for g in range(N_GROUPS):
                pair_weeks.append(And(x[w][g][p1], x[w][g][p2]))
        solver.add(Sum([If(pw, 1, 0) for pw in pair_weeks]) <= 1)

print("Solving...")
result = solver.check()
print(result)
if result == sat:
    m = solver.model()
    # Extract solution
    solution = [0] * (N_WEEKS * N_GOLFERS)
    for w in range(N_WEEKS):
        for p in range(N_GOLFERS):
            for g in range(N_GROUPS):
                if is_true(m.eval(x[w][g][p])):
                    solution[w * N_GOLFERS + p] = g
                    break
    print(solution)
else:
    print("UNSAT")

# Construct a Kirkman triple system of order 27 using AG(3,3)
# Points are vectors in GF(3)^3
# Lines are 1-dimensional affine subspaces

# GF(3) elements
GF3 = [0, 1, 2]

# All points
points = [(x, y, z) for x in GF3 for y in GF3 for z in GF3]

# Map point to index
point_to_idx = {p: i for i, p in enumerate(points)}

# All non-zero direction vectors (up to scalar multiplication)
# In GF(3), non-zero scalars are 1 and 2
# So each direction is represented by a vector, and v and 2v represent the same direction
directions = []
seen = set()
for a in GF3:
    for b in GF3:
        for c in GF3:
            if (a, b, c) == (0, 0, 0):
                continue
            # Normalize: multiply by 1 or 2 to get canonical form
            # We'll just check if any scalar multiple is already seen
            v = (a, b, c)
            v2 = ((2*a) % 3, (2*b) % 3, (2*c) % 3)
            if v not in seen and v2 not in seen:
                directions.append(v)
                seen.add(v)
                seen.add(v2)

print(f"Number of directions: {len(directions)}")
print(f"Directions: {directions}")

# For each direction, generate the parallel class
# A line in direction d starting at point p is {p + t*d : t in GF3}
# The parallel class partitions all points

def add_vec(v1, v2):
    return ((v1[0] + v2[0]) % 3, (v1[1] + v2[1]) % 3, (v1[2] + v2[2]) % 3)

def mul_scalar(s, v):
    return ((s * v[0]) % 3, (s * v[1]) % 3, (s * v[2]) % 3)

parallel_classes = []
for d in directions:
    # Find all lines in this direction
    used = set()
    lines = []
    for p in points:
        if p in used:
            continue
        line = []
        for t in GF3:
            pt = add_vec(p, mul_scalar(t, d))
            line.append(pt)
            used.add(pt)
        lines.append(line)
    parallel_classes.append(lines)

print(f"Number of parallel classes: {len(parallel_classes)}")
for i, pc in enumerate(parallel_classes):
    print(f"Class {i}: {pc}")

# Now we have 13 parallel classes. We need 7 weeks.
# Let's use the first 7 classes.
# Map each point to a golfer index (0..26)
# For each week, assign each line to a group (0..8)

weeks = 7
solution = [0] * (weeks * 27)

for w in range(weeks):
    pc = parallel_classes[w]
    for g, line in enumerate(pc):
        for pt in line:
            golfer_idx = point_to_idx[pt]
            solution[w * 27 + golfer_idx] = g

